var r2 = new AuthToken("user", "issuer", r1.ExpiresAt);
Console.WriteLine(r1 == r2);              // True — record value equality

class BrokenKey
{
    public string Tenant { get; set; } = "";
    public override bool Equals(object? obj) =>
        obj is BrokenKey other && Tenant == other.Tenant;
    // BUG: GetHashCode not overridden — still reference-based
}

var dict = new Dictionary<BrokenKey, int>();
var key1 = new BrokenKey { Tenant = "acme" };
dict[key1] = 42;
var key2 = new BrokenKey { Tenant = "acme" };
Console.WriteLine(dict.ContainsKey(key2)); // False — hash mismatch!
